import os
import abc
import logging
import subprocess
import six

from datetime import datetime
from .util import generate_random_string


class FileWriter(object):
    def __new__(self, log_dir, log_name, file_limit, add_line_number=False):
        if file_limit > 0:
            return MultiFileWriter(log_dir, log_name, file_limit, add_line_number)
        return SingleFileWritter(log_dir, log_name, add_line_number)


@six.add_metaclass(abc.ABCMeta)
class BaseFileWriter(object):

    def __init__(self, add_line_number):
        self._log_size = 0
        self._create_log_dir()
        self._remove_old_logs()
        self._add_line_number = add_line_number
        self._line_count = 1
        self._log = self._create_file_logger(self.log_path)

    @abc.abstractproperty
    def log_path(self):
        """Returns path to log file."""

    @abc.abstractmethod
    def write(self, data):
        """Method to write data to log file."""

    @abc.abstractmethod
    def _remove_old_logs(self):
        """Method to remove log directory."""

    @abc.abstractmethod
    def _create_log_dir(self):
        """Method to create log directory."""

    def clean_log(self):
        """Method to clean log file."""
        open(self.log_path, "w").close()

    def _create_file_logger(self, log_path):
        log = logging.getLogger(generate_random_string())
        log.addHandler(logging.FileHandler(log_path))
        log.setLevel(logging.DEBUG)
        return log

    def _create_dir(self, log_dir):
        try:
            os.makedirs(log_dir)
        except OSError as e:
            if e.errno == 17:
                try:
                    self._log.error(e)
                except AttributeError:
                    self._log = self._create_file_logger(self.log_path)
                    self._log.error(e)
            else:
                raise

    def _write(self, data):
        lines = self._filter_characters(data.split("\n"))
        for line in lines:
            line = '{} {}'.format(self._get_timestamp(), line)
            if self._add_line_number:
                line_number = str(self._line_count).zfill(6)
                self._line_count += 1
                line = '{} {}'.format(line_number, line)
            self._log_size += len(line)
            self._log.debug(line)

    def _filter_characters(self, data):
        filtered_lines = []
        for line in data:
            line = line.replace(chr(13), '')
            line = line.replace(chr(10), '')
            line = line.replace(chr(0), '')
            if line.strip():
                filtered_lines.append(line)
        return filtered_lines

    def _get_timestamp(self):
        return datetime.now().strftime("%d.%m %H:%M:%S.%f")

    def _remove_files(self, cwd, file_pattern):
        subprocess.call("rm -rf {}".format(file_pattern), shell=True, cwd=cwd)


class MultiFileWriter(BaseFileWriter):
    def __init__(self, log_dir, log_name, file_limit, add_line_number):
        self._log_dir = log_dir
        self._log_limit = file_limit
        self._log_number = 0
        self._log_base_name, self._log_ext = self._generate_log_name_parts(log_name)
        super(MultiFileWriter, self).__init__(add_line_number)

    @property
    def log_path(self):
        """Returns path to log file."""
        return self._get_log_path()

    def write(self, data):
        """Method to write data to log file."""
        if not self._log or self._log_size >= self._log_limit:
            self._log_path = self._create_log_path()
            self._log = self._create_file_logger(self._log_path)
            self._log_size = 0
        self._write(data)

    def _generate_log_name_parts(self, log_name):
        result = log_name.rsplit('.', 1)
        if len(result) > 1:
            return result[0], ".{}".format(result[1])
        return result[0], ""

    def _create_log_dir(self):
        self._create_dir(self._log_dir)

    def _create_log_path(self):
        self._log_number += 1
        return self._get_log_path()

    def _get_log_path(self):
        timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
        name = "{}_{}_{}{}".format(self._log_base_name, timestamp, self._log_number, self._log_ext)
        return os.path.join(self._log_dir, name)

    def _remove_old_logs(self):
        self._remove_files(self._log_dir, "{}_*{}".format(self._log_base_name, self._log_ext))


class SingleFileWritter(BaseFileWriter):
    def __init__(self, log_dir, log_name, add_line_number):
        self._log_dir = log_dir
        self._log_name = log_name
        self._log_path = os.path.join(log_dir, log_name)
        super(SingleFileWritter, self).__init__(add_line_number)

    @property
    def log_path(self):
        """Returns path to log file."""
        return self._log_path

    def write(self, data):
        """Method to write data to log file."""
        if not self._log:
            self._log = self._create_file_logger(self._log_path)
        self._write(data)

    def _create_log_dir(self):
        self._create_dir(self._log_dir)

    def _remove_old_logs(self):
        self._remove_files(self._log_dir, self._log_name)
